/* ============================================
   DIALOG COMPONENT
   General-purpose modal with backdrop overlay
   ============================================ */

.ds-dialog {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden; /* keeps panel controls out of the tab order when closed */
  pointer-events: none;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard), visibility var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-dialog--open {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}

/* ============================================
   BACKDROP
   ============================================ */

.ds-dialog__backdrop {
  position: absolute;
  inset: 0;
  background-color: var(--color-scrim);
}

/* ============================================
   PANEL
   ============================================ */

.ds-dialog__panel {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  gap: var(--gap-400); /* 16px */
  width: 100%;
  max-height: calc(100vh - var(--gap-1000) * 2); /* breathing room top/bottom */
  padding: var(--padding-500); /* 20px */
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-300); /* 12px */
  background-color: var(--color-bg-page-primary);
  box-shadow: var(--shadow-modal);
  transform: scale(0.96);
  transition: transform var(--motion-duration-base) var(--motion-ease-standard);
  outline: none;
}

.ds-dialog--open .ds-dialog__panel {
  transform: scale(1);
}

/* Sizes */
.ds-dialog--sm .ds-dialog__panel {
  max-width: 400px;
}

.ds-dialog--md .ds-dialog__panel {
  max-width: 560px;
}

.ds-dialog--lg .ds-dialog__panel {
  max-width: 720px;
}

/* ============================================
   HEADER
   ============================================ */

.ds-dialog__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--gap-400); /* 16px */
}

.ds-dialog__heading {
  display: flex;
  flex-direction: column;
  gap: var(--gap-100); /* 4px */
  min-width: 0;
}

.ds-dialog__title {
  font-family: var(--font-heading-3-family);
  font-size: var(--font-heading-3-size);
  font-weight: var(--font-heading-3-weight);
  line-height: var(--font-heading-3-line-height);
  letter-spacing: var(--font-heading-3-letter-spacing);
  color: var(--color-text-primary);
  margin: 0;
}

.ds-dialog__description {
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-tertiary);
  margin: 0;
}

/* Close button — ghost icon button */
.ds-dialog__close {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  padding: 0;
  border: none;
  border-radius: var(--radius-pill); /* pill */
  background-color: transparent;
  cursor: pointer;
  transition: background-color var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-dialog__close:hover {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-dialog__close:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
}

.ds-dialog__close-icon {
  --icon-size: var(--icon-size-500);
  line-height: 1;
  color: var(--color-icon-primary);
}

/* ============================================
   BODY
   Scrolls when content exceeds the panel height
   ============================================ */

.ds-dialog__body {
  overflow-y: auto;
  min-height: 0;
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  letter-spacing: var(--font-paragraph-letter-spacing);
  color: var(--color-text-secondary);
}

/* ============================================
   FOOTER
   ============================================ */

.ds-dialog__footer {
  display: flex;
  justify-content: flex-end;
  gap: var(--gap-200); /* 8px */
  padding-top: var(--padding-150); /* 6px */
}

/* ============================================
   RESPONSIVE
   ============================================ */

@media (max-width: 480px) {
  .ds-dialog__panel {
    margin: var(--padding-400);
  }
}

'use client';

import React, { useRef, useId } from 'react';
import ReactDOM from 'react-dom';
import './Dialog.css';
import '../../fonts/material-symbols.css';
import { useMounted } from '../../behaviors/useMounted';
import { useLayer } from '../../behaviors/useLayer';
import { useFocusScope } from '../../behaviors/useFocusScope';
import { useScrollLock } from '../../behaviors/useScrollLock';

/** Props owned by Dialog itself — everything else falls through to the panel. */
type DialogOwnProps = {
  /** Whether the dialog is open */
  open: boolean;
  /** Callback when dialog requests to close */
  onOpenChange: (open: boolean) => void;
  /**
   * Dialog title.
   * Note: this shadows the native `title` tooltip attribute, which Dialog does not expose.
   */
  title: string;
  /** Optional subtitle under the title */
  description?: string;
  /** Dialog body content */
  children?: React.ReactNode;
  /** Optional footer slot — typically a row of Buttons */
  footer?: React.ReactNode;
  /** Panel width */
  size?: 'sm' | 'md' | 'lg';
  /** Whether ESC, backdrop click, and the close button can dismiss */
  dismissible?: boolean;
  /** Additional CSS classes — applied to the portal container, not the panel */
  className?: string;
};

export interface DialogProps
  extends DialogOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof DialogOwnProps> {}

/**
 * Dialog component — a general-purpose modal with arbitrary
 * content and an optional footer. Traps focus, restores it on
 * close, locks body scroll, and supports ESC / backdrop / close
 * button dismissal. For confirm/cancel prompts use AlertDialog.
 *
 * Renders through a portal into `document.body`. The forwarded ref and any
 * unrecognised props target the **panel** (the `role="dialog"` element), not the
 * portal container — that is the element worth focusing or measuring.
 */
export const Dialog = React.forwardRef<HTMLDivElement, DialogProps>(
  (
    {
      open,
      onOpenChange,
      title,
      description,
      children,
      footer,
      size = 'md',
      dismissible = true,
      className = '',
      ...rest
    },
    ref,
  ) => {
    const panelRef = useRef<HTMLDivElement | null>(null);
    const titleId = useId();
    const descId = useId();
    const baseClass = 'ds-dialog';

    /** Keep the internal ref (used by the focus trap) while honouring a forwarded one. */
    const setPanelRef = (node: HTMLDivElement | null) => {
      panelRef.current = node;
      if (typeof ref === 'function') ref(node);
      else if (ref) ref.current = node;
    };

    // SSR guard — only render portal on the client
    const mounted = useMounted();

    // Shared overlay behaviors (src/behaviors/): Escape routes through the
    // layer stack so only the topmost overlay answers it; focus is trapped
    // and restored with the page inert behind the panel; the scroll lock is
    // counted, so closing this dialog over another modal keeps its lock.
    // Backdrop dismissal stays below — it is this component's own DOM.
    useLayer({ open, dismissOnEscape: dismissible, onDismiss: () => onOpenChange(false) });
    useFocusScope(panelRef, { active: open });
    useScrollLock(open);

    const handleBackdropClick = () => {
      if (dismissible) onOpenChange(false);
    };

    const containerClasses = [
      baseClass,
      `${baseClass}--${size}`,
      open ? `${baseClass}--open` : '',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    const dialog = (
      <div className={containerClasses}>
        <div className={`${baseClass}__backdrop`} onClick={handleBackdropClick} />

        <div
          {...rest}
          className={`${baseClass}__panel`}
          ref={setPanelRef}
          role="dialog"
          aria-modal="true"
          aria-labelledby={titleId}
          aria-describedby={description ? descId : rest['aria-describedby']}
          tabIndex={-1}
        >
          <div className={`${baseClass}__header`}>
            <div className={`${baseClass}__heading`}>
              <h2 className={`${baseClass}__title`} id={titleId}>
                {title}
              </h2>
              {description && (
                <p className={`${baseClass}__description`} id={descId}>
                  {description}
                </p>
              )}
            </div>

            {dismissible && (
              <button
                type="button"
                className={`${baseClass}__close`}
                onClick={() => onOpenChange(false)}
                aria-label="Close dialog"
              >
                <span
                  className={`${baseClass}__close-icon material-symbols-rounded`}
                  aria-hidden="true"
                >
                  close
                </span>
              </button>
            )}
          </div>

          {children && (
            // Scrollable when content is long; without a tab stop a keyboard
            // user cannot reach that scroll. The initial-focus query below
            // still prefers a real control, so this does not steal focus.
            <div className={`${baseClass}__body`} tabIndex={0}>
              {children}
            </div>
          )}

          {footer && <div className={`${baseClass}__footer`}>{footer}</div>}
        </div>
      </div>
    );

    if (!mounted) return null;
    return ReactDOM.createPortal(dialog, document.body);
  },
);

Dialog.displayName = 'Dialog';
